import pandas as pd
import numpy as np
from scipy import stats

# Load all experiments
exps = {}
for name in ['1','3','4','7','8','11']:
    try:
        df = pd.read_csv(f'experiment_{name}_csv')
        exps[name] = df
        print(f"\n=== experiment_{name} ===")
        print(f"Columns: {list(df.columns)}")
        print(df.describe().round(2))

        # Calculate correlations if we have multiple numeric columns
        numeric_cols = df.select_dtypes(include=[np.number]).columns.tolist()
        if 'unit_id' in numeric_cols:
            numeric_cols.remove('unit_id')
        if len(numeric_cols) >= 2:
            print(f"Correlations:")
            print(df[numeric_cols].corr().round(3))
    except Exception as e:
        print(f"Error loading experiment_{name}: {e}")

# Check for any actuator columns (those starting with 'do_' or showing constant values = fixed)
print("\n=== ACTUATOR DETECTION ===")
for name, df in exps.items():
    actuator_cols = [c for c in df.columns if c.startswith('do_')]
    if actuator_cols:
        print(f"exp{name}: actuators = {actuator_cols}, values = {df[actuator_cols].describe().iloc[-1].values}")

    # Check for constant columns (other than unit_id) that might indicate fixed actuators
    for col in df.columns:
        if col != 'unit_id' and df[col].std() == 0:
            print(f"exp{name}: {col} is constant at {df[col].iloc[0]}")

# Compare yields across experiments
print("\n=== YIELD COMPARISON ===")
for name in ['1','11']:
    if 'WaferYield' in exps[name].columns:
